create or replace function suggest_schedule_ejection_chain_v1(p_schedule_id uuid,p_weekday smallint,p_period smallint,p_limit smallint default 8) returns jsonb language plpgsql security definer set search_path=public as $$declare s teacher_schedule%rowtype;b teacher_schedule%rowtype;prof schedule_time_profiles%rowtype;d smallint;h smallint;m jsonb;pr jsonb;out jsonb:='[]'::jsonb;n int:=0;begin perform open_permission_context('schedule.edit');select * into s from teacher_schedule where id=p_schedule_id and active and institution_code=current_tenant_code();if not found or s.locked then return out;end if;select * into b from teacher_schedule where active and institution_code=current_tenant_code() and weekday=p_weekday and period=p_period and id<>s.id order by id limit 1;if not found or b.locked then return out;end if;if (select count(*) from teacher_schedule where active and institution_code=current_tenant_code() and weekday=p_weekday and period=p_period and id<>s.id)<>1 then return out;end if;select * into prof from schedule_time_profiles where active and tenant_row_allowed(institution_code) limit 1;if not found then return out;end if;foreach d in array prof.teaching_days loop for h in 1..prof.periods_per_day loop if (d=s.weekday and h=s.period) or (d=p_weekday and h=p_period) then continue;end if;m:=jsonb_build_array(jsonb_build_object('schedule_id',s.id,'weekday',p_weekday,'period',p_period),jsonb_build_object('schedule_id',b.id,'weekday',d,'period',h));pr:=preview_schedule_batch_move_v1(m);if coalesce((pr->>'ok')::boolean,false) then out:=out||jsonb_build_array(jsonb_build_object('kind','EJECTION_CHAIN_2','source_id',s.id,'ejected_id',b.id,'moves',m,'target',jsonb_build_object('weekday',p_weekday,'period',p_period),'ejected_target',jsonb_build_object('weekday',d,'period',h)));n:=n+1;if n>=greatest(1,least(p_limit,20)) then return out;end if;end if;end loop;end loop;return out;end$$;